export function HaspMark({ size = 32, color = '#4F35D2' }: { size?: number; color?: string; gap?: string }) {
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true" style={{ display: 'block', flexShrink: 0 }}>
      <path d={MARK} fill={color} fillRule="evenodd" />
    </svg>
  )
}

interface HaspLogoProps {
  fontSize?: number
  textColor?: string
  markColor?: string
  gapColor?: string
}

export default function HaspLogo({
  fontSize = 26,
  textColor = '#0F1226',
  markColor = '#4F35D2',
}: HaspLogoProps) {
  return (
    <div
      className="flex items-center"
      aria-label="Hasph"
      style={{ gap: fontSize * 0.4, userSelect: 'none', lineHeight: 1 }}
    >
      <HaspMark size={fontSize * 1.3} color={markColor} />
      <span
        style={{
          fontFamily: "'Inter', Arial, sans-serif",
          fontSize,
          fontWeight: 800,
          letterSpacing: '-0.035em',
          color: textColor,
        }}
      >
        Hasph
      </span>
    </div>
  )
}
